import json, html, shutil
from pathlib import Path
ROOT=Path(__file__).resolve().parents[1];FIX=ROOT/'tests/fixtures/cad-robustness-v2';OUT=ROOT/'public/benchmarks/cad-robustness-v2'
def main():
    fixture=json.loads((FIX/'cases.json').read_text());report=json.loads((ROOT/'artifacts/cad-robustness-v2/combined.json').read_text());rows={r['id']:r for r in report['rows']};OUT.mkdir(parents=True,exist_ok=True)
    for file in FIX.glob('*.png'): shutil.copy2(file,OUT/file.name)
    for name in ['cases.json','generation-prompt.txt']: shutil.copy2(FIX/name,OUT/name)
    (OUT/'fixtures').mkdir(exist_ok=True)
    for case in fixture['cases']: (OUT/'fixtures'/(case['id']+'.json')).write_text(json.dumps({'source':case['source'],'cases':[case]}))
    cards=[]
    for c in fixture['cases']:
        row=rows[c['id']];r=row.get('current') or {};result=r.get('result') or {};m=c['imageMap'];f=c['plane'];width,height=m['width'],m['height'];elements=[]
        def point(p):
            uv=[sum((p[k]-f['origin'][k])*f[a][k] for k in range(3)) for a in ['xAxis','yAxis']];return [width/2+(uv[0]-m['centerUV'][0])*m['pixelsPerMetre'],height/2-(uv[1]-m['centerUV'][1])*m['pixelsPerMetre']]
        def path(points,cls): return '<polyline class="'+cls+'" points="'+' '.join('%.2f,%.2f'%tuple(point(p)) for p in points)+'" fill="none"/>'
        for t in c['truth']: elements.append(path(t['points'],'truth'))
        for s in c['strokes']: elements.append(path(s['points'],'ink'))
        for fitted in result.get('results',[]): elements.append(path(fitted['pathWorld'],'reference' if fitted.get('construction') else 'fitted'))
        svg=f'<svg viewBox="0 0 {width} {height}" aria-label="{c["id"]}"><image class="source" href="{c["image"]}" width="{width}" height="{height}"/>'+''.join(elements)+'</svg>'
        failed=[k for k,v in r.get('checks',{}).items() if v is False];verdict='PASS' if r.get('pass') else 'REVIEW';metrics=r.get('metrics') or {};actual=f'{metrics.get("components","?")} outlines · {metrics.get("holes","?")} nested holes · {metrics.get("circles","?")} circles';expected=f'Expected {c["expected"]["components"]} outlines · {c["expected"]["holes"]} nested holes · {c["expected"]["circles"]} circles'
        details={'criteria':r.get('checks'),'metrics':metrics,'selectedRun':r.get('run'),'deterministicReplay':r.get('deterministicReplay'),'firstPass':row.get('first',{}).get('pass'),'firstCriteria':row.get('first',{}).get('checks'),'traceMerges':result.get('traceMerges'),'joinedChains':result.get('joinedChains'),'ignoredGroups':result.get('ignoredGroups'),'decisions':result.get('decisions'),'timings':result.get('timings'),'cost':result.get('cost'),'error':r.get('error')}
        cards.append(f'<article data-family="{c["family"]}" data-variant="{c["variant"]}" data-pass="{str(bool(r.get("pass"))).lower()}"><h2>{html.escape(c["family"])} <span class="{verdict.lower()}">{verdict}</span></h2><p>{c["variant"]}</p>{svg}<p>{actual}<br><small>{expected}</small></p><p class="issues">{html.escape(", ".join(failed) or r.get("error","") or "All defined checks met")}</p><a class="try-case" data-case="{c["id"]}" href="/desktop.html?experiment=decision">Try these strokes</a><details><summary>Measurements and model decisions</summary><pre>{html.escape(json.dumps(details,indent=2))}</pre></details></article>')
    s=report['summary'];table=''.join(f'<tr><td>{v}</td><td>{x["firstPass"]}/{x["cases"]}</td><td>{x["currentPass"]}/{x["cases"]}</td></tr>' for v,x in s['byVariant'].items());families=''.join(f'<option>{v}</option>' for v in dict.fromkeys(c['family'] for c in fixture['cases']));variants=''.join(f'<option>{v}</option>' for v in s['byVariant'])
    doc='''<!doctype html><html lang="en"><meta charset="utf-8"><meta name="viewport" content="width=device-width,initial-scale=1"><title>CAD stroke robustness</title><style>body{max-width:1440px;margin:28px auto;padding:0 24px;background:#f4f5f6;color:#233038;font:15px system-ui}h1{font-size:28px}h2{font-size:15px}p{line-height:1.55}main{display:grid;grid-template-columns:repeat(3,minmax(0,1fr));gap:16px}article{background:white;border:1px solid #dce1e3;border-radius:8px;padding:16px}article[hidden]{display:none}svg{width:100%;background:white;max-height:320px}.source{opacity:.3}.fitted{stroke:#087f83;stroke-width:2;stroke-linejoin:round}.truth{stroke:#315ecb;stroke-width:1;stroke-dasharray:5 3;display:none}.ink{stroke:#777;stroke-width:1;display:none}.reference{stroke:#9b7cb8;stroke-width:1;stroke-dasharray:6 4}.pass{color:#176d4c}.review,.issues{color:#9d452e}h2 span{float:right}pre{font-size:11px;white-space:pre-wrap;max-height:440px;overflow:auto}nav{display:flex;gap:12px;flex-wrap:wrap;align-items:center;margin:24px 0}select{padding:6px;font:inherit}a{color:#176878}table{border-collapse:collapse;font-size:13px}td,th{text-align:left;padding:6px 14px;border-bottom:1px solid #d5dcdf}@media(max-width:900px){main{grid-template-columns:1fr}}</style><h1>CAD stroke robustness</h1>'''
    doc+=f'<p>Four analytic mechanical profiles with known dimensions, plus four image-generated engineering sketches. <strong>{s["cases"]} cases; {s["currentPass"]} meet all defined checks.</strong> Most cases deliberately simulate poor drawing. These are development stress tests, not human-user accuracy.</p><p>Teal: fitted geometry. Grey: source ink. Blue dashed: known CAD truth. A REVIEW may still look close while losing a hole, rounded corner, closure or intended component.</p><table><tr><th>Stroke condition</th><th>First pass</th><th>Current decoder / selected retest</th></tr>{table}</table>'
    doc+=f'<p>Known inference spend across {s["attempts"]} attempts: <strong>${s["knownCostUSD"]:.5f}</strong>; {s["unknownUsage"]} attempts have unknown usage. Generation, audio, CAD agent and hosting are excluded. Current rows may replay saved model decisions through a corrected numerical decoder; they are not fresh accuracy samples. Earlier frozen results and failed attempts remain in the JSON.</p><p>Checks: outline/hole counts and containment; circular feature types; 6% per-feature contour deviation; 5% circle diameter and hole-center tolerance; local fillet/slot-arc error at most 20% of its radius; editable native argument validity. A missing-hole case expects only the holes actually drawn. Geometric checks do not establish 3D solidity or a native fillet feature.</p>'
    doc+='<nav><label>Family <select id="family"><option value="all">All</option>'+families+'</select></label><label>Condition <select id="variant"><option value="all">All</option>'+variants+'</select></label><label>Cases <select id="pass"><option value="all">All</option><option value="false">Needs review</option><option value="true">Passes</option></select></label><label>View <select id="view"><option value="overlay">Ink + fitted</option><option value="truth">Truth + fitted</option><option value="source">Source only</option><option value="fit">Fitted only</option></select></label><a href="report.json">Full evaluation</a><a href="cases.json">Stroke fixtures</a><a href="generated-sheet.png">Generated CAD sheet</a><a href="generation-prompt.txt">Generation prompt</a></nav><main>'+''.join(cards)+'''</main><script>for(const a of document.querySelectorAll('.try-case'))a.href='/desktop.html?experiment=decision&fixtureSet=cad-robustness-v2&fixture='+encodeURIComponent(a.dataset.case)+'&session='+crypto.randomUUID();for(const id of ['family','variant','pass'])document.querySelector('#'+id).onchange=()=>{for(const c of document.querySelectorAll('article'))c.hidden=['family','variant','pass'].some(k=>{const v=document.querySelector('#'+k).value;return v!=='all'&&c.dataset[k]!==v;});};document.querySelector('#view').onchange=e=>{const v=e.target.value;for(const n of document.querySelectorAll('.source')){n.style.display=['fit','truth'].includes(v)?'none':'';n.style.opacity=v==='source'?'1':'.3'}for(const n of document.querySelectorAll('.truth'))n.style.display=v==='truth'?'block':'none';for(const n of document.querySelectorAll('.fitted,.reference'))n.style.display=v==='source'?'none':'block';};</script></html>'''
    (OUT/'index.html').write_text(doc,encoding='utf-8');(OUT/'report.json').write_text(json.dumps(report,indent=2));shutil.copytree(OUT,ROOT/'dist/benchmarks/cad-robustness-v2',dirs_exist_ok=True);print(json.dumps({'path':str(OUT/'index.html'),'summary':s},indent=2))
if __name__=='__main__': main()
